// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SystemDetail) predicate.SystemDetail {
	return predicate.SystemDetail(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SystemDetail) predicate.SystemDetail {
	return predicate.SystemDetail(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SystemDetail) predicate.SystemDetail {
	return predicate.SystemDetail(sql.NotPredicates(p))
}
